      "faq_title": "Ce que les parents nous demandent",
      "faq_q1": "Y a-t-il un adulte qui dort avec les enfants la nuit ?",
      "faq_a1": "Oui. Une partie des pensionnaires adultes dorment avec les enfants la nuit pour assurer leur sécurité et leur encadrement en permanence.",
      "faq_q2": "Les enfants apprennent-ils uniquement le Coran, ou aussi à pratiquer la religion ?",
      "faq_a2": "Ils apprennent bien plus que la mémorisation : l'Unicité d'Allah (Tawhid), la jurisprudence islamique (Fiqh) et les invocations (Adhkar) du quotidien font partie intégrante du programme.",
      "faq_q3": "Les enseignants sont-ils expérimentés ?",
      "faq_a3": "Oui. 95 % du personnel a au moins 3 ans d'expérience. 80 % ont le niveau Licence (L3) en anglais, management ou sciences islamiques ; 5 % ont le niveau Master en management ou sciences islamiques.",
      "faq_q4": "Peut-on joindre son enfant pendant son pensionariat ?",
      "faq_a4": "Oui. Tous les dimanches, chaque enfant bénéficie de 10 minutes d'appel vocal avec ses parents. Les appels vidéo sont également autorisés.",
      "faq_q5": "En cas de souci de santé, comment procédez-vous ?",
      "faq_a5": "Nous contactons toujours les parents en premier lieu avant toute décision. En cas d'urgence extrême ne permettant pas d'attendre, l'enfant est conduit immédiatement à l'hôpital et les parents sont prévenus aussitôt.",
      "faq_q6": "Quelles mesures prenez-vous en cas de problème disciplinaire ?",
      "faq_a6": "Aucun châtiment corporel. Les sanctions éducatives sont : privation d'activités de divertissement, augmentation du temps d'apprentissage ou tâches ménagères. Nous appliquons une méthode rigoureusement sans violence.",
      "faq_q7": "Qui s'occupe de la toilette des enfants ?",
      "faq_a7": "Les enfants de 6 à 7 ans sont accompagnés et aidés par une surveillante. Les plus grands sont contrôlés quotidiennement ; les manquements à l'hygiène font l'objet de sanctions éducatives.",
      "faq_q8": "Les enfants peuvent-ils être frappés s'ils se comportent mal ?",
      "faq_a8": "Non, formellement non. Il est impératif de ne jamais porter la main sur un enfant. Cette règle est absolue et sans exception à Al Amine Academy.",
