      "faq_title": "Vous vous demandez…",
      "faq_q1": "Mon fils a 7 ans, peut-il aller à la Villa de la Petite Côte ?",
      "faq_a1": "Non. La Villa de la Petite Côte est réservée aux <strong>garçons à partir de 7 ans et demi</strong>. Pour les plus jeunes ou les filles, le programme de la Cité des Magistrats à Dakar est ouvert à tous.",
      "faq_q2": "Puis-je inscrire mon enfant pour seulement un mois ?",
      "faq_a2": "Oui. Les tarifs sont mensuels, vous choisissez la durée du séjour entre le 5 juillet et le 25 septembre 2026.",
      "faq_q3": "Comment communiquer avec mon enfant pendant le séjour ?",
      "faq_a3": "Les téléphones personnels sont interdits. Des moments d'appel encadrés sont organisés régulièrement avec les familles via les téléphones de l'équipe, durant les dimanches, de 12 heures à 19 heures. Pour une durée maximale de 20 minutes par élève.",
      "faq_q4": "L'externat inclut-il les activités sportives ?",
      "faq_a4": "Non. Les externants suivent uniquement les cours de Coran de <strong>9 h à 17 h</strong>, avec un déjeuner inclus. Les activités sport sont réservées aux internes.",
      "faq_q5": "Que se passe-t-il en cas de manquement au règlement ?",
      "faq_a5": "Tout manquement entraîne une sanction proportionnée. En cas de faute grave (objet ou substance interdite), l'exclusion définitive du camp est immédiate.",
      "faq_q6": "Puis-je visiter les locaux avant d'inscrire mon enfant ?",
      "faq_a6": "Bien sûr. Contactez-nous au <a href=\"tel:+221777743700\" class=\"text-primary font-semibold\">+221 77 774 37 00</a> ou via WhatsApp pour planifier une visite.",
      "faq_more": "Voir plus de questions",
