      "rentree_title": "The Boys' Tahfiz Boarding School is Moving to Cité SOCABEG",
      "rentree_intro_html": "Tahfiz remains a <strong>boarding-only</strong> program (no day-school option), open to both boys and girls:",
      "rentree_boys_html": "<strong>Boys</strong>: new boarding facility at <strong>Cité SOCABEG</strong> — 60 seconds from the stadium, a 5-minute walk from the Cité des Magistrats boarding house.",
      "rentree_girls_html": "<strong>Girls</strong>: boarding at <strong>Cité des Magistrats</strong>, in the former boys' building, now entirely reserved for girls (Tahfiz and Mixed Program).",
