      "faq_q1": "My son is 7, can he go to the Villa de la Petite Côte?",
      "faq_a1": "No. The Villa de la Petite Côte is reserved for <strong>boys aged 7 and a half and up</strong>. For younger children or girls, the Cité des Magistrats program in Dakar is open to everyone.",
