      "faq_a2": "Yes. Rates are monthly, you choose the length of stay between July 5 and September 25, 2026.",
      "faq_q3": "How can I communicate with my child during the stay?",
      "faq_a3": "Personal phones are forbidden. Supervised call times are regularly organized with families via staff phones, on Sundays from 12pm to 7pm, for a maximum of 20 minutes per student.",
