      "faq_badge": "Preguntas frecuentes",
      "faq_title": "¿Tienes dudas?",
      "faq_q1": "Mi hijo tiene 7 años, ¿puede ir a la Villa de la Petite Côte?",
      "faq_a1": "No. La Villa de la Petite Côte está reservada para <strong>niños a partir de 7 años y medio</strong>. Para los más pequeños o las niñas, el programa de Cité des Magistrats en Dakar está abierto a todos.",
      "faq_q2": "¿Puedo inscribir a mi hijo por solo un mes?",
      "faq_a2": "Sí. Las tarifas son mensuales, eliges la duración de la estancia entre el 5 de julio y el 25 de septiembre de 2026.",
      "faq_q3": "¿Cómo puedo comunicarme con mi hijo durante la estancia?",
      "faq_a3": "Los teléfonos personales están prohibidos. Se organizan regularmente momentos de llamada supervisados con las familias a través de los teléfonos del equipo, los domingos de 12h a 19h, por un máximo de 20 minutos por alumno.",
      "faq_q4": "¿El externado incluye actividades deportivas?",
      "faq_a4": "No. Los alumnos externos solo asisten a las clases de Corán de <strong>9h a 17h</strong>, con almuerzo incluido. Las actividades deportivas están reservadas para los internos.",
      "faq_q5": "¿Qué ocurre en caso de incumplimiento del reglamento?",
      "faq_a5": "Cualquier incumplimiento conlleva una sanción proporcional. En caso de falta grave (objeto o sustancia prohibida), la expulsión definitiva del campamento es inmediata.",
      "faq_q6": "¿Puedo visitar las instalaciones antes de inscribir a mi hijo?",
      "faq_a6": "Por supuesto. Contáctanos al <a href=\"tel:+221777743700\" class=\"text-primary font-semibold\">+221 77 774 37 00</a> o por WhatsApp para planificar una visita.",
      "faq_more": "Ver más preguntas",
      "faq_less": "Ver menos preguntas",
