      "karang_desc": "Un proyecto humanitario y educativo llevado a cabo por Al Amine Academy en beneficio de la población de Karang — gestionado de forma independiente del campamento de vacaciones.",
      "karang_subtitle": "«Los Benefactores» — al servicio de la comunidad",
